//!
//! Integration test binaries in this workspace masquerade as the real Codex
//! CLI so they can dispatch to helpers such as `apply_patch` and
//! `codex-linux-sandbox` based on their arg0. This crate centralizes that
//! setup so each test crate does not have to reimplement the same
//! `#[ctor]` bootstrapping logic.

use std::ffi::OsString;
use std::path::Path;

use codex_arg0::Arg0DispatchPaths;
use codex_arg0::Arg0PathEntryGuard;
use codex_arg0::arg0_dispatch;

const CODEX_HOME_ENV_VAR: &str = "CODEX_HOME";

/// Guard returned by [`configure_test_binary_dispatch`] when arg0 aliases are
/// installed. Holds the temporary `CODEX_HOME` directory alive for the process
/// lifetime along with the arg0 PATH-entry guard.
pub struct TestBinaryDispatchGuard {
    /// Keeps the temporary `CODEX_HOME` directory alive.
    _codex_home: tempfile::TempDir,
    /// Keeps the per-session PATH entry (and its alias symlinks) alive.
    arg0: Arg0PathEntryGuard,
    /// The `CODEX_HOME` value observed before we installed aliases, retained so
    /// the guard documents what was restored.
    _previous_codex_home: Option<OsString>,
}

impl TestBinaryDispatchGuard {
    /// Returns the helper executable paths captured while installing aliases.
    pub fn paths(&self) -> &Arg0DispatchPaths {
        self.arg0.paths()
    }
}

/// Controls what [`configure_test_binary_dispatch`] does for the current
/// process invocation, as decided by the caller-provided `classify` closure.
pub enum TestBinaryDispatchMode {
    /// Dispatch via arg0 (e.g. run `apply_patch` or `codex-linux-sandbox`) and
    /// return `None` without installing aliases.
    DispatchArg0Only,
    /// Do nothing and return `None`.
    Skip,
    /// Set up a temporary `CODEX_HOME`, install arg0 dispatch aliases, restore
    /// the previous `CODEX_HOME`, and return the resulting guard.
    InstallAliases,
}

/// Reads argv0/argv1, asks `classify` how to handle this invocation, and acts
/// accordingly. Intended to be invoked from a `#[ctor]` static initializer in
/// test binaries, before any test threads are spawned.
///
/// * [`TestBinaryDispatchMode::DispatchArg0Only`] dispatches via arg0 and
///   returns `None`.
/// * [`TestBinaryDispatchMode::Skip`] returns `None`.
/// * [`TestBinaryDispatchMode::InstallAliases`] creates a temporary
///   `CODEX_HOME` (using `codex_home_prefix` as the directory prefix), installs
///   arg0 dispatch aliases under it, restores the previous `CODEX_HOME`, and
///   returns `Some(TestBinaryDispatchGuard)`.
pub fn configure_test_binary_dispatch<F>(
    codex_home_prefix: &str,
    classify: F,
) -> Option<TestBinaryDispatchGuard>
where
    F: FnOnce(&str, Option<&str>) -> TestBinaryDispatchMode,
{
    let mut args = std::env::args_os();
    let argv0 = args.next().unwrap_or_default();
    let exe_name = Path::new(&argv0)
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("");
    let argv1 = args.next().unwrap_or_default();

    match classify(exe_name, argv1.to_str()) {
        TestBinaryDispatchMode::DispatchArg0Only => {
            // arg0_dispatch() dispatches to the appropriate helper based on
            // argv0/argv1 and typically exits the process; if it returns we
            // simply drop the (unused) guard.
            let _ = arg0_dispatch();
            None
        }
        TestBinaryDispatchMode::Skip => None,
        TestBinaryDispatchMode::InstallAliases => {
            let codex_home = tempfile::Builder::new()
                .prefix(codex_home_prefix)
                .tempdir()
                .ok()?;
            let previous_codex_home = std::env::var_os(CODEX_HOME_ENV_VAR);

            // arg0_dispatch() creates helper links under CODEX_HOME/tmp. Point
            // it at a test-owned temp dir so startup never mutates the
            // developer's real ~/.codex.
            //
            // Safety: this is intended to run from #[ctor] before tests start,
            // so no test threads exist yet.
            unsafe {
                std::env::set_var(CODEX_HOME_ENV_VAR, codex_home.path());
            }

            let arg0 = arg0_dispatch();

            // Restore the process environment immediately so later tests
            // observe the same CODEX_HOME state they started with.
            match previous_codex_home.as_ref() {
                Some(value) => unsafe {
                    std::env::set_var(CODEX_HOME_ENV_VAR, value);
                },
                None => unsafe {
                    std::env::remove_var(CODEX_HOME_ENV_VAR);
                },
            }

            Some(TestBinaryDispatchGuard {
                _codex_home: codex_home,
                arg0: arg0?,
                _previous_codex_home: previous_codex_home,
            })
        }
    }
}
